<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
class TahunAnggaran extends Model { protected $table='tahun_anggaran'; protected $fillable=['tahun','status']; public function pendapatan():HasMany{return $this->hasMany(Pendapatan::class);} public function belanja():HasMany{return $this->hasMany(Belanja::class);} public function pembiayaan():HasMany{return $this->hasMany(Pembiayaan::class);} public function bidang():HasMany{return $this->hasMany(Bidang::class);} public function dokumen():HasMany{return $this->hasMany(DokumenPublikasi::class);} public function scopeAktif($q){return $q->where('status','aktif');} }
